function fractionForY(y, vh, h, margin = PILL_MARGIN) {
  const freeY = Math.max(0, vh - h - 2 * margin);
  if (freeY === 0) return PILL_DEFAULT_Y;
  return Math.max(0, Math.min(1, (y - margin) / freeY));
}

